contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We capture values before and after calling Put to assert consistency between
    // the public Acc getter and the contract balance and that balance increased correctly.
    function run(uint unlockTime, uint amount) public payable {
        require(address(this).balance >= amount);

        // Read pre-state via public getter Acc(address) which returns Holder (unlockTime,balance)
        (uint beforeUnlock, uint beforeBal) = c.Acc(address(this));
        uint cBalBefore = address(c).balance;

        bool reverted;
        // Call Put with specified unlockTime and amount sent.
        try c.Put{value: amount}(unlockTime) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read post-state
        (uint afterUnlock, uint afterBal) = c.Acc(address(this));
        uint cBalAfter = address(c).balance;

        // If the call reverted then state must be unchanged (post equals pre) and contract balance unchanged.
        // If call did not revert then the recorded balance must have increased by exactly 'amount' and
        // contract Ether balance must have increased by at least 'amount'. Also unlockTime updated to
        // max(previous, block.timestamp) or to the provided unlockTime if that was greater. We cannot
        // refer to block.timestamp captured earlier, but we can assert monotonicity: afterUnlock >= beforeUnlock.

        assert( (reverted && afterBal == beforeBal && cBalAfter == cBalBefore && afterUnlock == beforeUnlock)
                || (!reverted && afterBal == beforeBal + amount && cBalAfter >= cBalBefore + amount && afterUnlock >= beforeUnlock) );
    }

    // Allow receiving refunds if any
    receive() external payable { }
}

