    // and amount to attempt to Collect (collectAmt). We must fund this contract with depAmt before calling Put.
    function run(uint putUnlock, uint depAmt, uint collectAmt) public payable {
        // ensure this test contract can send the deposit
        require(address(this).balance >= depAmt);

        // Read pre-state for this test contract's Holder in c
        (uint beforeUnlock, uint beforeBal) = c.Acc(address(this));
        uint cBalBefore = address(c).balance;

        // Deposit depAmt via Put (call may revert if any internal require fails)
        bool putReverted;
        try c.Put{value: depAmt}(putUnlock) {
            putReverted = false;
        } catch {
            putReverted = true;
        }

        // Read intermediate state after Put attempt
        (uint midUnlock, uint midBal) = c.Acc(address(this));
        uint cBalMid = address(c).balance;

        // Now attempt Collect of collectAmt; capture whether it reverted
        bool collectReverted;
        try c.Collect{value: 0}(collectAmt) {
            collectReverted = false;
        } catch {
            collectReverted = true;
