contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will deposit funds (via Put) then try Collect and observe outcomes.
    function run(uint unlockOffset, uint putAmount, uint collectAmount) public payable {
        require(address(this).balance >= putAmount, "insufficient balance for put");
        // ensure unlockOffset is a future time relative to current block to allow control
        uint unlockTime = block.timestamp + unlockOffset;

        // initial observed balance recorded in c for this contract
        (uint beforeUnlockTime, uint beforeBal) = c.Acc(address(this));

        // Put funds into c for this contract
        c.Put{value: putAmount}(unlockTime);

        // observe after put
        (uint afterUnlockTime, uint afterBal) = c.Acc(address(this));
        // sanity: afterBal must be at least beforeBal (put shouldn't reduce recorded balance)
        // Note: this is an intermediate check but not the final assert
        require(afterBal >= beforeBal, "put decreased balance");

        // record contract Ether balance before collect
        uint contractBalanceBefore = address(c).balance;
        uint recordedBalanceBeforeCollect = afterBal;

        // attempt to Collect collectAmount and capture whether it reverted
        bool reverted;
        try c.Collect{value: 0}(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // observe recorded balance and contract balance after collect attempt
        (uint finalUnlockTime, uint finalRecordedBal) = c.Acc(address(this));
        uint contractBalanceAfter = address(c).balance;

        // General rule assert:
        // - The recorded balance for this test contract never increases from recordedBalanceBeforeCollect
        // - If Collect succeeded (not reverted) then either recorded decreased by exactly collectAmount and contract ETH decreased by collectAmount,
        //   or if nothing was allowed by contract logic (conditions not met) then recorded balance stayed the same.
        // This assertion is expressed without underflow by comparing sums.
        assert(
            // recorded never increases
            finalRecordedBal <= recordedBalanceBeforeCollect
            && (
                // Case A: reverted -> recorded unchanged (Collect reverted shouldn't change stored balance)
                (reverted && finalRecordedBal == recordedBalanceBeforeCollect)
                ||
                // Case B: not reverted -> either balance decreased by collectAmount and c's ether decreased by collectAmount,
                // ensuring no underflow by using addition comparisons
                (!reverted &&
                    (recordedBalanceBeforeCollect == finalRecordedBal + collectAmount && contractBalanceBefore == contractBalanceAfter + collectAmount)
                )
            )
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We assert that a successful Put call atomically increments both the on-chain ether held by c
    // and the recorded Acc balance for this contract by exactly the value sent.
    // Parameters:
    //   uint unlockOffset - seconds added to block.timestamp to form unlockTime (can be 0)
    //   uint putAmount - amount of wei to send with Put
    function run(uint unlockOffset, uint putAmount) public payable {
        // ensure this test contract has enough ether to send putAmount
        require(address(this).balance >= putAmount, "insufficient balance for put");

        // observe recorded balance before
        (uint beforeUnlock, uint beforeBal) = c.Acc(address(this));
        uint contractBalBefore = address(c).balance;

        // compute unlock time parameter
        uint unlockTime = block.timestamp + unlockOffset;

        // perform Put with value putAmount
        c.Put{value: putAmount}(unlockTime);

        // observe after
        (uint afterUnlock, uint afterBal) = c.Acc(address(this));
        uint contractBalAfter = address(c).balance;

        // General rule (single assert):
        // - recorded balance increased by exactly putAmount
        // - contract's ether balance increased by exactly putAmount
        // We express exact increase by sums to avoid underflow.
        assert(afterBal == beforeBal + putAmount && contractBalAfter == contractBalBefore + putAmount);
    }

