}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Parameters:
    //  uint putAmount - amount to deposit via Put (wei)
    //  uint unlockOffset - seconds added to block.timestamp to set unlockTime (>0 to allow Collect later)
    //  uint collectAmount - amount to attempt to Collect
    function run(uint putAmount, uint unlockOffset, uint collectAmount) public payable {
        // ensure test contract has enough ether to send putAmount
        require(address(this).balance >= putAmount);

        // initial recorded balance for this test contract in c
        (, uint beforeBal) = c.Acc(address(this));
        uint cBalBefore = address(c).balance;

        // Do a Put to potentially increase recorded balance (may be zero if putAmount==0)
        uint unlockTime = block.timestamp + unlockOffset;
        c.Put{value: putAmount}(unlockTime);

        // record after Put
        (, uint afterPutBal) = c.Acc(address(this));
        uint cBalAfterPut = address(c).balance;

        // attempt Collect and catch revert
        bool reverted;
        try c.Collect(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // observe after Collect
        (, uint afterCollectBal) = c.Acc(address(this));
        uint cBalAfterCollect = address(c).balance;

        // General invariant to hold for all inputs:
        // The recorded balance for this test contract never increases as a result of Collect.
        // Thus afterCollectBal <= afterPutBal.
        // Additionally, if Collect succeeded (not reverted) and reduced recorded balance, then
        // the decrease in recorded balance is at most the ether decrease of contract c.
        // (We avoid asserting exact equality to accommodate external call failure handling.)
        assert(afterCollectBal <= afterPutBal && (reverted || afterPutBal - afterCollectBal <= cBalAfterPut - cBalAfterCollect));
    }

    receive() external payable {}
}
